if __name__ == "__main__":
    selected = sys.argv[sys.argv.index("--")+1:] if "--" in sys.argv else list(ASSET_IDS)
    for asset_id in selected or ASSET_IDS:
        if asset_id not in ASSET_IDS:
            raise ValueError("Unknown equipment asset: "+asset_id)
        export(asset_id)

if __name__ == "__main__":
    selected = sys.argv[sys.argv.index("--")+1:] if "--" in sys.argv else list(ASSET_IDS)
    if not selected:
        selected = list(ASSET_IDS)
    for asset_id in selected:
        if asset_id not in ASSET_IDS:
            raise ValueError("Unknown logistics asset: " + asset_id)
        reset()
        root = build(asset_id)
        finish(asset_id, root)
        write_anchor_manifest(asset_id, root)

if __name__ == '__main__':
    builders = (
        ('rack-high', build_rack_high),
        ('rack-low', build_rack_low),
        ('environment-shell', build_environment_shell),
        ('dock', build_dock),
    )
    selected = sys.argv[sys.argv.index('--')+1:] if '--' in sys.argv else []
    for asset_id, builder in builders:
        if selected and asset_id not in selected:
            continue
        reset()
        finish(asset_id, builder())
